// WebAssembly Client-Side Cryptographic Black Box (ChaCha20 Engine)
// Decrypts Divine, HELL and Milestone vault items purely inside compiled WASM linear memory.
// Keys are generated on-the-fly inside WASM registers via non-linear arithmetic
// and zeroed from memory immediately after decryption. No server API needed!
const WasmVault = (() => {
  let wasmInstance = null;
  let initPromise = null;
  const blobCache = new Map();

  // Base64-encoded compiled vault.wasm (923 bytes)
  const WASM_BASE64 = "";

  // Embedded offline/file:// encrypted payloads for Divine, HELL & Milestone Rewards
  const EMBEDDED_VAULT_PAYLOADS = {
    "case opening/vault/loot_divine.enc": "",
    "case opening/vault/loot_hell.enc": "",
    "case opening/vault/loot_milestone_dinocura.enc": "U791IK/0YOeF0qiUcgmM7SrZq1ni5ck1Bu/8emqyKm8RLKTMUptMP0iHM4EFiY/9gCmzfxSKE7sQfQxRM0rObrvQFSGT28UjmEXheiC/MH966vXAO29p/oTKtKhYAjKrF+o6a0YKJmdB4YjDRXqljsLXdsH+q1SjxYqeEjtpcW2cWORaP9aFh7jOBUeVro0Ji6I+R7Vt2ZXKtVdkln1MVHmJcHls5zHXmbszpyz7Yu/cqpSe5uTSZzC/aoyPMw==",
    "case opening/vault/loot_milestone_krof_grindset.enc": "",
    "case opening/vault/loot_milestone_nikola_peder.enc": "",
    "case opening/vault/loot_milestone_vito.enc": "2Y2nTXvsxOjXPrKbu9UOr795dFsbKuXvRoMo9BiCVOzVLAVTaP+diLXFYqGXAmavk3IfZrk+ZsnCqnITWXB/63IyVkhVv/oz7bpe52DX+JwnQ826frMxN/geeBuwe/OGlfiraSKJq0r9Ks3m+yY+ZjrsTB24s60KLe5eRP9TbTrWDTbkOMRuZc9bKDguz0Y5U/C2kwHAMh+oSv4mdwJRD1Vj+T+WBAPPHRkprHS4rtipQJ0l",
    "case opening/vault/loot_milestone_wyz_cigani.enc": ""
};

  async function init() {
    if (wasmInstance) return wasmInstance;
    if (initPromise) return initPromise;

    initPromise = (async () => {
      try {
        if (typeof WebAssembly === 'undefined') {
          throw new Error('WebAssembly is not supported in this browser.');
        }
        const binStr = atob(WASM_BASE64);
        const len = binStr.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binStr.charCodeAt(i);
        }
        const result = await WebAssembly.instantiate(bytes, {});
        wasmInstance = result.instance;
        return wasmInstance;
      } catch (err) {
        console.error('[WasmVault] Failed to initialize WebAssembly:', err);
        throw err;
      }
    })();

    return initPromise;
  }

  // Decrypt raw Uint8Array payload (nonce + ciphertext)
  async function decrypt(itemCode, payloadBytes) {
    const instance = await init();
    const memory = instance.exports.memory;
    const bufPtr = instance.exports.get_buffer_ptr();
    const decryptPayload = instance.exports.decrypt_payload;

    const neededBytes = bufPtr + payloadBytes.length + 128;
    if (neededBytes > memory.buffer.byteLength) {
      const pagesToGrow = Math.ceil((neededBytes - memory.buffer.byteLength) / 65536);
      memory.grow(pagesToGrow);
    }

    // Write payload into WASM linear memory
    const memView = new Uint8Array(memory.buffer);
    memView.set(payloadBytes, bufPtr);

    // Call WASM decryption (executes ChaCha20 inside WASM registers, then zeroes keys)
    const plainLen = decryptPayload(itemCode, payloadBytes.length);
    if (plainLen <= 0) {
      throw new Error('WASM decryption failed: invalid item code or corrupt ciphertext');
    }

    // Copy decrypted bytes out of WASM memory
    const decryptedBytes = new Uint8Array(plainLen);
    decryptedBytes.set(new Uint8Array(memory.buffer, bufPtr + 16, plainLen));

    // Zero out memory region after extraction
    new Uint8Array(memory.buffer, bufPtr, payloadBytes.length).fill(0);

    return decryptedBytes;
  }

  // Decrypt vault file by relative path and return cached blob: URL
  async function decryptFile(vaultFilePath, itemCode, mimeType = 'image/jpeg') {
    if (blobCache.has(vaultFilePath)) {
      return blobCache.get(vaultFilePath);
    }

    let payload = null;
    try {
      const resp = await fetch(vaultFilePath);
      if (resp && resp.ok) {
        const arrayBuffer = await resp.arrayBuffer();
        payload = new Uint8Array(arrayBuffer);
      }
    } catch (fetchErr) {
      // fetch fails on file:// or offline; fallback to embedded payload
    }

    if (!payload && typeof EMBEDDED_VAULT_PAYLOADS !== 'undefined') {
      const normPath = String(vaultFilePath).replace(/\\/g, '/');
      const b64 = EMBEDDED_VAULT_PAYLOADS[normPath] || EMBEDDED_VAULT_PAYLOADS[vaultFilePath];
      if (b64) {
        const binStr = atob(b64);
        const len = binStr.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binStr.charCodeAt(i);
        }
        payload = bytes;
      }
    }

    if (!payload) {
      throw new Error('Failed to load encrypted vault file: ' + vaultFilePath);
    }

    const decryptedBytes = await decrypt(itemCode, payload);

    const blob = new Blob([decryptedBytes], { type: mimeType });
    const blobUrl = URL.createObjectURL(blob);
    blobCache.set(vaultFilePath, blobUrl);
    return blobUrl;
  }

  // Decrypt JSON payload directly
  async function decryptJson(vaultFilePath, itemCode) {
    const key = vaultFilePath + ':json';
    if (blobCache.has(key)) {
      return blobCache.get(key);
    }

    let payload = null;
    try {
      const resp = await fetch(vaultFilePath);
      if (resp && resp.ok) {
        payload = new Uint8Array(await resp.arrayBuffer());
      }
    } catch (e) {}

    if (!payload && typeof EMBEDDED_VAULT_PAYLOADS !== 'undefined') {
      const normPath = String(vaultFilePath).replace(/\\/g, '/');
      const b64 = EMBEDDED_VAULT_PAYLOADS[normPath] || EMBEDDED_VAULT_PAYLOADS[vaultFilePath];
      if (b64) {
        const binStr = atob(b64);
        const bytes = new Uint8Array(binStr.length);
        for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
        payload = bytes;
      }
    }

    if (!payload) {
      throw new Error('Failed to load encrypted JSON file: ' + vaultFilePath);
    }

    const decryptedBytes = await decrypt(itemCode, payload);
    const text = new TextDecoder('utf-8').decode(decryptedBytes);
    const parsed = JSON.parse(text);
    blobCache.set(key, parsed);
    return parsed;
  }

  // Eagerly initialize WASM runtime in background
  if (typeof window !== 'undefined') {
    setTimeout(() => init().catch(() => {}), 50);
  }

  return {
    init,
    decrypt,
    decryptFile,
    decryptJson
  };
})();

window.WasmVault = WasmVault;
